/// <summary>
///     The <c>AVAProdDateHistoryController</c> class is the controller class for <c>AVAProdDateHistory</c>
/// </summary>
class AVAProdDateHistoryController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
///     AVA <c>new</c> method.
/// </summary>
protected void new()
{
    super();

    this.parmClassName(classStr(AVAProdDateHistoryService));
    this.parmMethodName(methodStr(AVAProdDateHistoryService, runService));
}

/// <summary>
///     AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
/// <returns>
///     <c>AVAProdDateHistoryController</c> as return value
/// </returns>
public static AVAProdDateHistoryController newFromArgs(Args _args)
{
    AVAProdDateHistoryController controller;

    controller = new AVAProdDateHistoryController();
    controller.parmArgs(_args);
    // remove for activating value initialization of AVABPJobsContract.initialize()
    controller.parmLoadFromSysLastValue(false);

    return controller;
}

/// <summary>
///     AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVAProdDateHistoryController    controller;
    AVAProdDateHistoryContract      dataContract;
    SysOperationStartResult         sysOperationStartResult;

    controller              = AVAProdDateHistoryController::newFromArgs(_args);
    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);

    dataContract            = controller.getDataContractObject() as AVAProdDateHistoryContract;
    dataContract.parmArgs(_args);

    sysOperationStartResult = controller.startOperation();

    if(sysOperationStartResult == SysOperationStartResult::Started)
    {
        info(strFmt("@SYS82282", "@NDX:NXAOperationStarted"));
    }
}
